/**
 * Sign the Android release build with xorr's own release key, not Expo's debug key.
 *
 * `android/` is generated by `expo prebuild` and gitignored, so the signing config is injected here on every prebuild.
 * The keystore and its passwords never enter the repo: they are read from Gradle properties, normally set in
 * `$GRADLE_USER_HOME/gradle.properties` (or `-P` on the command line):
 *
 *   XORR_RELEASE_STORE_FILE=/absolute/path/xorr-clockin-release.keystore
 *   XORR_RELEASE_STORE_PASSWORD=…
 *   XORR_RELEASE_KEY_ALIAS=xorr-clockin
 *   XORR_RELEASE_KEY_PASSWORD=…
 *
 * Without them the release build falls back to the debug key, as Expo's template does, and says so in the build log.
 */
const { withAppBuildGradle } = require('expo/config-plugins');

const BLOCK = `
        release {
            if (project.hasProperty('XORR_RELEASE_STORE_FILE')) {
                storeFile file(XORR_RELEASE_STORE_FILE)
                storePassword XORR_RELEASE_STORE_PASSWORD
                keyAlias XORR_RELEASE_KEY_ALIAS
                keyPassword XORR_RELEASE_KEY_PASSWORD
            }
        }`;

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    let g = cfg.modResults.contents;
    if (g.includes('XORR_RELEASE_STORE_FILE')) return cfg;
    // Add a `release` signing config next to Expo's `debug` one.
    g = g.replace(/signingConfigs\s*\{/, (m) => `${m}${BLOCK}`);
    // The release build type uses it when the key is configured, else the debug key.
    g = g.replace(
      /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/,
      `$1signingConfig project.hasProperty('XORR_RELEASE_STORE_FILE') ? signingConfigs.release : signingConfigs.debug`,
    );
    cfg.modResults.contents = g;
    return cfg;
  });
};
